import React from 'react';

import PohBadge from '@ui-kit/Badge/Badge';
import PohCollapsible, { IPohCollapsibleProps } from '@ui-kit/Collapsible';
import PohCollapsibleIcon from '@ui-kit/Collapsible/PohCollapsibleIcon';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IHikingCollapsibleHeaderProps extends IPohCollapsibleProps {
  id: string;
  header: React.ReactNode;
  toolbar?: React.ReactNode;
  count?: number;
}

const HikingCollapsibleBlock = ({
  id,
  header,
  toolbar,
  children,
  count = 0,
  ...rest
}: IHikingCollapsibleHeaderProps) => {
  return (
    <PohCollapsible
      {...rest}
      activatorComponent={(open) => (
        <PohRow as="header" className="toolbared">
          <PohCol
            as="h4"
            id={id}
            sm={toolbar ? 4 : 12}
            className="mt-3 mb-2 d-flex align-items-center"
          >
            <PohCollapsibleIcon open={open} className="me-1 ms-n4 show-on-hover" />
            {header}
            {count > 0 && !open && (
              <PohBadge rounded as="small" className="ms-1">
                {count}
              </PohBadge>
            )}
          </PohCol>

          {!!toolbar && open && (
            <PohCol
              sm={8}
              className="text-end align-self-end p-2"
              onClick={(e) => e.stopPropagation()}
            >
              {toolbar}
            </PohCol>
          )}
        </PohRow>
      )}
    >
      {children}
    </PohCollapsible>
  );
};

export default HikingCollapsibleBlock;
