import React from 'react';

import { iAmHikingRadish } from '@apps/Hiking/@services/hikingRadish.service';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { radishConfirmAsync } from './HikingRadishModal/hikingRadishModal.helper';
import radish from '../../../../../img/SF_Radish.svg';

interface IHikingBottomMenuProps {
  id_hiking: number;
}

const HikingBottomMenu: React.FC<IHikingBottomMenuProps> = ({ id_hiking }) => {
  const handleRadish = async () => {
    const confirmText = await radishConfirmAsync();

    if (confirmText) {
      if (
        window.confirm(
          'Последний шанс передумать...\nВы уверены что хотите отказаться от этого похода?',
        )
      ) {
        try {
          await iAmHikingRadish({
            comment: confirmText,
            id_hiking,
          });
          notificationHelper.success('Вы успешно отказались от похода :(');
        } catch (er) {
          notificationHelper.error((er as Error).message);
          window.location.reload();
        }
      }
    } else {
      notificationHelper.success('Мы рады что ты остаешься с нами :)');
    }
  };

  return (
    <PohRow as="footer" className="d-flex justify-content-between">
      <PohCol sm={2} md={{ span: 6 }} className="text-center text-md-start">
        <PohButton icon={true} onClick={handleRadish} title="Отказаться от участи я в походе :(">
          <img src={radish} height={24} width={24} />
        </PohButton>
      </PohCol>
      <PohCol sm={10} md={{ span: 6 }} className="ms-0 ms-md-auto text-center text-md-end">
        <PohButton href={`/hiking/${id_hiking}/workouts`} variant={ButtonVariant.Light}>
          Тренировки
        </PohButton>
        {' | '}
        <PohButton href={`/hiking/${id_hiking}/equip`} variant={ButtonVariant.Primary}>
          Собрать рюкзак
        </PohButton>
        {' | '}
        <PohButton href={`/hiking/${id_hiking}/menu`} variant={ButtonVariant.Light}>
          Вариант меню
        </PohButton>
        {' | '}
        <PohButton href={`/hiking/${id_hiking}/finance`} variant={ButtonVariant.Light}>
          Финансы
        </PohButton>
      </PohCol>
    </PohRow>
  );
};

export default HikingBottomMenu;
