import React from 'react';

import { warn } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';

interface IHikingRadishModalProps {
  onSend: (text: string) => void;
  onCancel: () => void;
}

const HikingRadishModal: React.FC<IHikingRadishModalProps> = ({ onSend, onCancel }) => {
  const [text, setText] = React.useState('');
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (text.trim().length === 0) {
          warn('Мы пытаемся кого-то обмануть?)');
          return;
        }

        onSend(text);
      }}
    >
      <textarea
        autoFocus
        rows={10}
        required
        className="form-control"
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Обязательный комментарий. Почему вы не идете в поход..."
      />
      <div className="mt-3 pt-3 mb-n2 text-end">
        <PohButton variant={ButtonVariant.Primary} type="button" onClick={onCancel}>
          Отмена
        </PohButton>
        &nbsp; &nbsp;
        <PohButton variant={ButtonVariant.Light} type="submit">
          Выйти из похода
        </PohButton>
      </div>
    </form>
  );
};

export default HikingRadishModal;
