import PohAva from '@ui-kit/Ava';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';

const EquipItem = ({
  name,
  photo,
  isConfirm,
}: {
  name: string;
  photo: string;
  isConfirm: boolean;
}) => (
  <div className="d-flex align-items-center justify-content-between">
    <div className="d-flex align-items-center">
      <PohAva src={photo} alt={name} className="my-n1 ms-n2 me-2" />
      {name}
    </div>
    <span title={!isConfirm ? 'Ожидает утверждения' : 'Утверждено'}>
      <PohIcon
        name={!isConfirm ? IconsEnum.watch : IconsEnum.check}
        style={{ fill: !isConfirm ? 'tomato' : 'green' }}
      />
    </span>
  </div>
);

export default EquipItem;
