import React from 'react';

import { CardLink } from 'react-bootstrap';
import { Link, useNavigate } from 'react-router-dom';

import { getHikingObstaclesList } from '@apps/Hiking/@services/hikingObstacles.service';
import { IHikingObstacleWithObstacleListItem } from '@apps/Hiking/@types/hikingObstacles.types';
import HikingObstacleListItem from '@apps/Hiking/obstacles/HikingObstacleListItem';
import { getUrlFromObstacleType } from '@apps/Obstacles/@mappers/obstacles.url.mapper';
import {
  obstacleCategoryNameResource,
  obstacleTypeNameResource,
} from '@apps/Obstacles/@resources/obstacles.resource';
import { getRouteObjectsAsync } from '@apps/Routes/@services/routes.service';
import { IBaseRouteObjectPoint, RouteObjectType } from '@apps/Routes/@types/routes.types';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCard from '@ui-kit/Card';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import HikingCollapsibleBlock from '../HikingCollapsibleBlock';

interface IHikingObstaclesProps {
  id_hiking: number;
  id_route: number;
}

const HikingObstacles: React.FC<IHikingObstaclesProps> = ({ id_route, id_hiking }) => {
  const [roWithObstacles, setRoWithObstacles] = React.useState<IBaseRouteObjectPoint[]>([]);
  const [hikingObstacles, setHikingObstacles] = React.useState<
    IHikingObstacleWithObstacleListItem[]
  >([]);
  const navigate = useNavigate();
  React.useEffect(() => {
    getRouteObjectsAsync(id_route).then((data) => {
      const fd = data.filter(
        (d) => d.type === RouteObjectType.Point && d.obstacle !== null,
      ) as IBaseRouteObjectPoint[];
      setRoWithObstacles(fd);
    });

    getHikingObstaclesList(id_hiking).then(setHikingObstacles);
  }, [id_route]);

  if (!roWithObstacles.length) return null;
  return (
    <HikingCollapsibleBlock
      id="obstacles"
      header={hikingObstacles.length > 0 ? `Посещенные места` : `Интересные места`}
      count={hikingObstacles.length}
    >
      {hikingObstacles.length > 0 && (
        <PohList
          data={hikingObstacles.map((ho) => {
            return {
              key: ho.id,
              children: <HikingObstacleListItem obstacleItem={ho} />,
              action: true,
              onClick: () => navigate(`/hiking/${id_hiking}/obstacles/${ho.obstacle.id}/${ho.id}`),
            };
          })}
        />
      )}
      {!hikingObstacles.length && (
        <div>
          <PohRow className="d-flex">
            {roWithObstacles.map((ro) => {
              if (!ro.obstacle) return null;
              return (
                <PohCol sm={3} key={ro.id}>
                  <PohCard
                    key={ro.id}
                    title={ro.obstacle?.name}
                    subtitle={
                      <div className="d-flex">
                        {obstacleTypeNameResource[ro.obstacle.type]}
                        &nbsp;
                        <PohBadge className="ms-auto" variant={BadgeVariant.Warning}>
                          <small>{obstacleCategoryNameResource[ro.obstacle.category]}</small>
                        </PohBadge>
                      </div>
                    }
                    text={
                      <>
                        {/* {ro.obstacle?.description && <small>{ro.obstacle.description}</small>}
                {ro.obstacle?.comment && <em>{ro.obstacle.comment}</em>} */}
                      </>
                    }
                    links={[
                      <CardLink
                        as={Link}
                        key={ro.id}
                        to={`/obstacles/${getUrlFromObstacleType(ro.obstacle.type)}/${ro.obstacle?.id}`}
                      >
                        Подробнее
                      </CardLink>,
                    ]}
                    className="mb-2"
                  ></PohCard>
                </PohCol>
              );
            })}
          </PohRow>
        </div>
      )}
    </HikingCollapsibleBlock>
  );
};

export default HikingObstacles;
