import React from 'react';

import { useNavigate } from 'react-router-dom';

import { getHikingWeather } from '@apps/Hiking/@services/hikingWeather.service';
import { IHikingWeather } from '@apps/Hiking/@types/hikingWeather.types';
import { round } from '@helpers/mathHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohButton from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohImagePlaceholder from '@ui-kit/ImagePlaceholder';
import { confirmModal } from '@ui-kit/Modal';

import HikingCollapsibleBlock from '../HikingCollapsibleBlock';
import d01 from './icons/d01.svg';
import d02 from './icons/d02.svg';
import d03 from './icons/d03.svg';
import d04 from './icons/d04.svg';
import d09 from './icons/d09.svg';
import d10 from './icons/d10.svg';
import d11 from './icons/d11.svg';
import d13 from './icons/d13.svg';

const degToCard = function (deg: number) {
  const directions = [
    'С',
    'ССВ',
    'СВ',
    'ВСВ',
    'В',
    'ВЮВ',
    'ЮВ',
    'ЮЮВ',
    'Ю',
    'ЮЮЗ',
    'ЮЗ',
    'ЗЮЗ',
    'З',
    'ЗСЗ',
    'СЗ',
    'ССЗ',
  ];
  const i = (deg + 11.25) / 22.5;
  return directions[i % 16];
};

const iconsSrcs: Record<string, any> = {
  '01d': d01, // clear sky
  '02d': d02, // few clouds
  '03d': d03, // df
  '04d': d04, // broken clouds
  '09d': d09, // shower rain
  '10d': d10, // rain
  '11d': d11, // thunderstorm
  '13d': d13, // snow
};

const WeatherWidget = ({ id_hiking }: { id_hiking: number }) => {
  const [days, setDays] = React.useState<IHikingWeather[]>([]);

  const navigate = useNavigate();

  const update = React.useCallback(() => {
    getHikingWeather(id_hiking).then((res) => {
      setDays(res);
    });
  }, []);

  React.useEffect(() => {
    update();
  }, [update]);

  const handleInfo = () => {
    confirmModal({
      confirmText: 'Настроить',
      children: (
        <p>
          Вы можете зарегистрироваться на сайте{' '}
          <a href="http://sms.ru" target="_blank" rel="noreferrer">
            sms.ru
          </a>{' '}
          и добавть свой номер телефона и apiKey в{' '}
          <a target="_blank" rel="noreferrer" href="/profile#phones">
            личном кабинете походника
          </a>
          .
          <br />
          Во время похода вам будет приходить прогноз погоды на 2 дня в виде СМС.
        </p>
      ),
    }).then((ok) => {
      ok && navigate('/profile#phones');
    });
  };

  return (
    <HikingCollapsibleBlock
      id="weather"
      header="Погода"
      toolbar={
        <>
          <small className="text-muted"></small>
          <PohButton icon={IconsEnum.info} onClick={handleInfo} />
          <PohButton
            icon={IconsEnum.refresh}
            onContextMenu={async (e) => {
              try {
                (e.target as HTMLButtonElement).disabled = true;
                await fetch('/cron/long_forecast.php?id_hiking=' + id_hiking);
                await fetch('/cron/short_forecast.php?id_hiking=' + id_hiking);
                await fetch('/cron/tomorrow_forecast.php?id_hiking=' + id_hiking);
                e.altKey &&
                  (await fetch('/cron/tomorrow_forecast_more.php?id_hiking=' + id_hiking));
                notificationHelper.success('Обновлено');
              } catch (err) {
                notificationHelper.error((err as Error).message);
              }
            }}
            onClick={async () => {
              update();
            }}
          />
        </>
      }
      count={days?.length}
      open
    >
      {days && (
        <div style={{ overflowX: 'auto' }}>
          <div className="my-2 text-center text-nowrap">
            {days.map((day) => {
              const weather = day.forecast.weather[0];
              return (
                <PohCard
                  className="me-1 d-inline-block text-center"
                  style={{
                    minWidth: '180px',
                    maxWidth: '180px',
                    background: 'linear-gradient(to bottom, #9be2fe 0%, #67d1fb 100%)',
                  }}
                  key={day.date.toISOString()}
                >
                  <PohImagePlaceholder
                    src={
                      iconsSrcs[weather.icon] ||
                      `//openweathermap.org/img/w/${day.forecast.weather[0].icon}.png`
                    }
                    style={{ width: 64, height: 64 }}
                    iconName={IconsEnum.close}
                    alt={day.forecast.weather[0].description}
                  />
                  <br />
                  {day.date.toLocaleDateString()}
                  <br />
                  <small className="mt-n3 text-muted mb-1 text-truncate" title={day?.name}>
                    {day.name || day?.name}
                  </small>
                  <br />
                  <div className="text-truncate" title={weather.description}>
                    {weather.description || (
                      <small className="text-muted">Прогноз недоступен</small>
                    )}
                  </div>
                  <br />
                  <small className="d-flex text-center mx-n3 mt-2">
                    <span className="p-1 w-25">
                      <small className="d-block text-muted">ночь</small>
                      {round(day.forecast.temp.night, 1) || '-'}
                    </span>
                    <span className="p-1 w-25 border-start">
                      <small className="d-block text-muted">утро</small>
                      {round(day.forecast.temp.morn, 1) || '-'}
                    </span>
                    <span className="p-1 w-25 border-start">
                      <small className="d-block text-muted">день</small>
                      {round(day.forecast.temp.day, 1) || '-'}
                    </span>
                    <span className="p-1 w-25 border-start">
                      <small className="d-block text-muted">вечр</small>
                      {round(day.forecast.temp.eve, 1) || '-'}
                    </span>
                  </small>

                  <small className="d-flex text-center mx-n3 border-top">
                    <span className="p-1 w-25" title="Ветер м/c, *-N порывы">
                      {round(day.forecast.speed, 0) || '-'}
                      {day.forecast.gust > +day.forecast.speed + 3 && (
                        <>-{round(day.forecast.gust, 0)}</>
                      )}
                      <small className="d-block text-muted">
                        {day.forecast.deg !== undefined ? degToCard(day.forecast.deg) : '-'}
                      </small>
                    </span>
                    <span
                      className="p-1 w-25 border-start"
                      title={'Осадки, мм. \nВероятность осадков'}
                    >
                      {day.forecast.rain && day.forecast.pop > 0.19 && (
                        <>
                          <small>💧</small>{' '}
                          {round(day.forecast.rain ?? day.forecast.snow, 0) || '-'}
                        </>
                      )}
                      {day.forecast.snow && day.forecast.pop > 0.19 && (
                        <>
                          <small>❄</small>{' '}
                          {round(day.forecast.rain ?? day.forecast.snow, 0) || '-'}
                        </>
                      )}
                      {day.forecast.pop < 0.2 && '-'}
                      <small className="d-block text-muted">
                        {day.forecast.pop ? round(day.forecast.pop * 100, 0) : 0}%
                      </small>
                    </span>
                    <span
                      className="p-1 w-25 border-start"
                      title="Атмосферное давление, мм. рт. ст."
                    >
                      {Math.round(0.75006375541921 * day.forecast.pressure) || '-'}
                      <small className="d-block text-muted">мм.р.с</small>
                    </span>
                    <span className="p-1 w-25 border-start" title="Облачность, %">
                      {day.forecast.clouds || '-'}
                      <small className="d-block text-muted">☁</small>
                    </span>
                  </small>

                  <small
                    className="d-flex nx-n3 mt-2 justify-content-between align-items-center"
                    title={`Прод. св. дн.: ${new Date(day.forecast.sunset * 1e3 - day.forecast.sunrise * 1e3 + new Date().getTimezoneOffset() * 60 * 1000).toLocaleTimeString().substr(0, 5)}`}
                  >
                    <small>
                      {new Date(day.forecast.sunrise * 1e3).toLocaleTimeString().substr(0, 5)}
                    </small>
                    <small>☀️</small>
                    <small>
                      {new Date(day.forecast.sunset * 1e3).toLocaleTimeString().substr(0, 5)}
                    </small>
                  </small>
                </PohCard>
              );
            })}
          </div>
        </div>
      )}
    </HikingCollapsibleBlock>
  );
};

export default WeatherWidget;
