import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getDomain } from '@helpers/domain.helper';

import facebookIcon from '../../../../../img/icons/social/facebook.social.svg';
import googlePlusIcon from '../../../../../img/icons/social/google_plus.social.svg';
import twitterIcon from '../../../../../img/icons/social/twitter.social.svg';
import vkIcon from '../../../../../img/icons/social/vk.social.svg';

const HikingShare: React.FC = () => {
  const hikingData = React.useContext(HikingContext);

  if (!hikingData) return null;

  const surl = `https://${getDomain()}/hiking/${hikingData.id}`;
  const stitle = `Присоединяйся к походу ${hikingData.name}`;
  const simage = `https://org.pohodnik58.ru/${hikingData.visual.bg}`;
  const shashtags = [
    'поход',
    hikingData.name ? hikingData.name.replace(/\s/g, '') : '',
    hikingData.region.name ? hikingData.region.name.replace(/\s/g, '') : '',
  ].join(',');

  const share: Array<{
    title: string;
    url: string;
    params: Record<string, string>;
    iconUrl: string;
  }> = [
    {
      title: 'Твитнуть в twitter',
      url: '//twitter.com/intent/tweet',
      params: {
        text: stitle,
        hashtags: shashtags,
        url: surl,
        via: 'pohodnik58',
      },
      iconUrl: twitterIcon,
    },
    {
      title: 'Поделиться в vk',
      url: '//vk.com/share.php',
      params: {
        url: surl,
        title: stitle,
        image: simage,
        description: hikingData.desc,
      },
      iconUrl: vkIcon,
    },
    {
      title: 'Поделиться в google+',
      url: '//plus.google.com/share',
      params: { url: surl, text: stitle, image: simage },
      iconUrl: googlePlusIcon,
    },
    {
      title: 'Поделиться в facebook',
      url: '//www.facebook.com/sharer.php',
      params: { u: surl },
      iconUrl: facebookIcon,
    },
  ];

  return (
    <section style={{ margin: '50px 0' }} className={'text-center hiking-sharing'}>
      <h3>Расскажите друзьям о походе</h3>
      {share.map((s) => {
        return (
          <a
            key={s.title}
            href={`${s.url}?${new URLSearchParams(s.params).toString()}`}
            target="_blank"
            title={s.title}
            className="ms-2"
            role="external-link"
            rel="noreferrer"
          >
            <img src={s.iconUrl} width={26} height={26} />
          </a>
        );
      })}
    </section>
  );
};

export default HikingShare;
