import { IRouteObject, RouteObjectType } from '@apps/Routes/@types/routes.types';

export const inDistanceLineFilter = (line: IRouteObject) =>
  line.type === RouteObjectType.Line && line.is_in_distance;
export const notInDistanceLineFilter = (line: IRouteObject) =>
  line.type === RouteObjectType.Line && !line.is_in_distance;
export const pointsFilter = (line: IRouteObject) =>
  line.type === RouteObjectType.Point && !line.obstacle;
export const withObstaclesPointsFilter = (line: IRouteObject) =>
  line.type === RouteObjectType.Point && line.obstacle;
