import React, { useContext } from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { HikingAccessGroupContext } from '@apps/Hiking/@contexts/hikingPrivilegesContext';
import { getHikingDataAsync } from '@apps/Hiking/@services/hiking.service';
import {
  getUncompletedUserRadish,
  uncompletedRadishUpdate,
} from '@apps/Hiking/@services/hikingRadish.service';
import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import { HikingAccessGroup } from '@apps/Hiking/@types/hiking.rules';
import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import HikingPageEquipWidget from '@apps/Hiking/equip/HikingEquip/HikingPageEquipWidget';
import { requestUncompletedRadishCommentAsync } from '@apps/Hiking/radish/RadishUncompleted/RadishUncompleted';
import Page from '@components/Page';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';

import styles from './styles.module.less';
import HeaderWidget from '../components/HeaderWidget';
import HikingBottomMenu from '../components/HikingBottomMenu';
import HikingComments from '../components/HikingComments';
import HikingObstacles from '../components/HikingObstacles';
import HikingRoute from '../components/HikingRoute';
import HikingSchedule from '../components/HikingSchedule';
import HikingShare from '../components/HikingShare';
import HikingText from '../components/HikingText';
import HikingVacancies from '../components/HikingVacancies';
import MembersWidget from '../components/MembersWidget';
import WeatherWidget from '../components/WeatherWidget';

interface IHikingOneProps {
  id_hiking: number;
}

const HikingOne: React.FC<IHikingOneProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData>();
  const [accessGroup, setHikingAccessGroup] = React.useState(HikingAccessGroup.Readonly);
  const [isLoading, setIsLoading] = React.useState(true);
  const [error, setError] = React.useState<Error>();

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const fetchedHikingData = await getHikingDataAsync(id_hiking);
        setHikingData(fetchedHikingData);
        const accessGroupRes = await getHikingAccessGroupAsync(id_hiking);
        setHikingAccessGroup(accessGroupRes);
      } catch (e) {
        setError(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking]);

  React.useEffect(() => {
    // Параноидальная проверка не редиска ли зашел посмотреть поход
    getUncompletedUserRadish().then(async (uncompletedRadish) => {
      if (uncompletedRadish?.length) {
        uncompletedRadish.forEach(async (radish) => {
          const comment = await requestUncompletedRadishCommentAsync(radish);
          await uncompletedRadishUpdate(+radish.id, comment);
          notificationHelper.success('Спасибо. Учли');
        });
      }
    });
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (error) {
    return <PohAlert>{error.message}</PohAlert>;
  }

  if (!hikingData) {
    return <PohAlert>С этим походом что-то не так</PohAlert>;
  }

  const isTimeout = hikingData.finish < new Date();
  const isIHiker = !!hikingData.hikers.find(
    (h) => authContext.user && h.idUser === +authContext.user.id,
  );

  const keywords = [
    'Походники',
    'Поход',
    hikingData.type.name,
    hikingData.region.name,
    hikingData.name,
  ];

  return (
    <Page
      title={hikingData.name}
      description={hikingData.desc}
      image={hikingData.visual.photo}
      keywords={keywords}
    >
      <HikingContext.Provider value={hikingData}>
        <HikingAccessGroupContext.Provider value={accessGroup}>
          <meta property="article:section" content={hikingData.type.name} />
          <meta property="article:published_time" content={hikingData.start.toISOString()} />

          <meta property="og:locality" content={hikingData.region.name} />

          <section className={styles.hikingOne} id="content">
            <HeaderWidget />
            <MembersWidget isAllowJoin={!isIHiker && !isTimeout} />
            <HikingText id_hiking={id_hiking} />
            {!isTimeout && isIHiker && <HikingVacancies id_hiking={id_hiking} />}

            <HikingSchedule />

            {!!hikingData.route.id && (
              <HikingObstacles id_hiking={id_hiking} id_route={hikingData.route.id} />
            )}
            <HikingRoute />
            <WeatherWidget id_hiking={id_hiking} />
            <HikingPageEquipWidget id_hiking={id_hiking} />
            {!isTimeout && isIHiker && <HikingBottomMenu id_hiking={id_hiking} />}
            <HikingShare />
            <HikingComments id_hiking={id_hiking} />
          </section>
        </HikingAccessGroupContext.Provider>
      </HikingContext.Provider>
    </Page>
  );
};

export default HikingOne;
