import { hikingVacancyAddResponse } from '@apps/Hiking/@services/hikingPositionsAndVacancies.service';
import { IHikingVacancy } from '@apps/Hiking/@types/hikingPositionsAndVacancies.types';
import showModalAboutPositionAsync from '@apps/Hiking/positions/helpers/positionInfoHelper';
import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';

function Vacancy({ data, id_hiking }: { data: IHikingVacancy; id_hiking: number }) {
  return (
    <div
      title={data.position.description}
      className="d-flex justify-content-between align-items-center"
    >
      <div>
        <strong>{data.position.name}</strong> до {new Date(data.deadline).toLocaleDateString()}{' '}
        <PohIcon name={IconsEnum.help} />
      </div>
      <PohButton
        title=""
        onClick={async () => {
          try {
            const ok = await showModalAboutPositionAsync(data.position.id, 'Откликнуться');
            if (ok) {
              const { success: ss } = await hikingVacancyAddResponse({
                id_hiking,
                id_vacancy: data.id,
              });
              ss && success('Заявка принята');
            }
          } catch (ee) {
            err(ee as Error);
          }
        }}
        variant={ButtonVariant.OutlinePrimary}
        size={ButtonSize.Small}
        className="my-n1"
      >
        Подробнее
      </PohButton>
    </div>
  );
}

export default Vacancy;
