import React from 'react';

import { Link } from 'react-router-dom';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { AuthContext } from '@contexts/AuthContext';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';

import HikingCollapsibleBlock from '../HikingCollapsibleBlock';
import HikingRouteCompleted from './components/HikingRouteCompleted';
import HikingRoutePlanned from './components/HikingRoutePlanned';
import HikingRouteVote from './components/HikingRouteVote';
import HikingRouteDownloadButton from './HikingRouteDownloadButton';

const HikingRoute: React.FC = () => {
  const hikingData = React.useContext(HikingContext);
  const authContext = React.useContext(AuthContext);

  const isIHiker = React.useMemo(() => {
    if (!hikingData) return false;
    if (!authContext.user) return false;
    return !!hikingData.hikers.find((h) => h.idUser === authContext.user?.id);
  }, [authContext.user?.id]);

  const isCompleted = React.useMemo(() => {
    if (!hikingData) return false;
    return hikingData.finish < new Date();
  }, [hikingData?.finish]);

  if (!hikingData) return null;

  if (hikingData.route.id && isCompleted) {
    return (
      <HikingCollapsibleBlock
        id="route"
        header="Маршрут"
        toolbar={
          <>
            <Link
              to={`/hiking/${hikingData.id}/hiking_route_info/${hikingData.route.id}`}
              target="_blank"
            >
              Передвижения
            </Link>
            <Link className="ms-2" to={`/routes/${hikingData.route.id}`} target="_blank">
              Плановый маршрут
            </Link>
            <HikingRouteDownloadButton />
          </>
        }
        open
      >
        <HikingRouteCompleted id_hiking={hikingData.id} id_route={hikingData.route.id} />
      </HikingCollapsibleBlock>
    );
  }

  if (hikingData.route.id) {
    return (
      <HikingCollapsibleBlock
        id="route"
        header="Маршрут"
        open
        toolbar={
          <>
            <PohButton
              as={Link as any}
              to={`/hiking/${hikingData.id}/hiking_route_info/${hikingData.route.id}`}
              target={'_blank'}
              size={ButtonSize.Small}
              variant={ButtonVariant.Light}
            >
              Передвижения
            </PohButton>
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Light}
              className="ms-2"
              as={Link as any}
              to={`/routes/${hikingData.route.id}`}
            >
              Открыть маршрут
            </PohButton>
            <HikingRouteDownloadButton />
          </>
        }
      >
        <HikingRoutePlanned id_route={hikingData.route.id} />
      </HikingCollapsibleBlock>
    );
  }

  if (hikingData.route.isVacant) {
    if (!isIHiker) {
      return (
        <>
          Присоединившись к походу вы сможете предложить свой маршрут или выбрать наиболее
          интересный вариант
        </>
      );
    }

    return <HikingRouteVote id_hiking={hikingData.id} />;
  }
  return null;
};

export default HikingRoute;
