import React from 'react';

import * as L from 'leaflet';

import {
  IBaseRouteObjectLine,
  IBaseRouteObjectPoint,
  IRouteObject,
  RouteObjectType,
} from '@apps/Routes/@types/routes.types';
import RoutesEditorListItem from '@apps/Routes/RouteEditorNew/components/RoutesEditorSidebar/RoutesEditorListItem';
import { formatDistance } from '@helpers/formatHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohList from '@ui-kit/List';
import PohTabs, { IPohTab } from '@ui-kit/Tabs';

import {
  inDistanceLineFilter,
  withObstaclesPointsFilter,
  notInDistanceLineFilter,
  pointsFilter,
} from './filters';
import style from './style.module.less';

interface IHikingRouteToolbarProps {
  name: string;
  map: L.Map;
  routeObjects: IRouteObject[];
}

const HikingRouteToolbar: React.FC<IHikingRouteToolbarProps> = ({ name, map, routeObjects }) => {
  const [collapse, setCollapse] = React.useState(false);

  const handleToggle = () => setCollapse((x) => !x);

  if (collapse) {
    return (
      <PohButton icon={IconsEnum.info} variant={ButtonVariant.Primary} onClick={handleToggle} />
    );
  }

  const inDistance = routeObjects.filter(inDistanceLineFilter) as IBaseRouteObjectLine[];
  const notInDistance = routeObjects.filter(notInDistanceLineFilter) as IBaseRouteObjectLine[];
  const points = routeObjects.filter(pointsFilter) as IBaseRouteObjectPoint[];
  const obstaclesPoints = routeObjects.filter(withObstaclesPointsFilter) as IBaseRouteObjectPoint[];

  const handleClickRouteObject = (ro: IRouteObject) => {
    ro.type === RouteObjectType.Line
      ? map.flyToBounds(new L.Polyline(ro.points).getBounds())
      : map.flyTo(ro.coordinates);
  };

  const tabs: IPohTab[] = [];

  if (inDistance?.length > 0) {
    tabs.push({
      key: '1',
      title: (
        <>
          Маршрут &nbsp;
          <PohBadge variant={BadgeVariant.Success}>
            {formatDistance(inDistance.reduce((sum, cur) => sum + +cur.distance, 0))}
          </PohBadge>
        </>
      ),
      content: (
        <div className={style.list}>
          <PohList
            data={inDistance.map((line) => ({
              key: line.id,
              action: true,
              onClick: () => handleClickRouteObject(line),
              onDoubleClick: () => {
                handleClickRouteObject(line);
                handleToggle();
              },
              content: <RoutesEditorListItem routeObject={line} />,
              className: 'p-0',
            }))}
          />
        </div>
      ),
    });
  }

  if (notInDistance?.length > 0) {
    tabs.push({
      key: '2',
      title: (
        <>
          Запаски &nbsp;
          <PohBadge variant={BadgeVariant.Info}>
            <del>{formatDistance(notInDistance.reduce((sum, cur) => sum + cur.distance, 0))}</del>
          </PohBadge>
        </>
      ),
      content: (
        <div className={style.list}>
          <PohList
            data={routeObjects.filter(notInDistanceLineFilter).map((line) => ({
              key: line.id,
              action: true,
              onClick: () => handleClickRouteObject(line),
              onDoubleClick: () => {
                handleClickRouteObject(line);
                handleToggle();
              },
              content: <RoutesEditorListItem routeObject={line} />,
              className: 'p-0',
            }))}
          />
        </div>
      ),
    });
  }

  if (points?.length > 0) {
    tabs.push({
      key: '3',
      title: (
        <>
          Точки &nbsp;
          <PohBadge variant={BadgeVariant.Warning}>{points?.length}</PohBadge>
        </>
      ),
      content: (
        <div className={style.list}>
          <PohList
            data={points.map((line) => {
              return {
                key: line.id,
                action: true,
                onClick: () => handleClickRouteObject(line),
                onDoubleClick: () => {
                  handleClickRouteObject(line);
                  handleToggle();
                },
                content: <RoutesEditorListItem routeObject={line} />,
                className: 'p-0',
              };
            })}
          />
        </div>
      ),
    });
  }

  if (obstaclesPoints?.length > 0) {
    tabs.push({
      key: '4',
      title: (
        <>
          Перевалы &nbsp;
          <PohBadge variant={BadgeVariant.Warning}>{obstaclesPoints?.length}</PohBadge>
        </>
      ),
      content: (
        <div className={style.list}>
          <PohList
            data={obstaclesPoints.map((line) => ({
              key: line.id,
              action: true,
              onClick: () => handleClickRouteObject(line),
              onDoubleClick: () => {
                handleClickRouteObject(line);
                handleToggle();
              },
              content: <RoutesEditorListItem routeObject={line} />,
              className: 'p-0',
            }))}
          />
        </div>
      ),
    });
  }

  return (
    <div
      onWheel={(e) => {
        e.stopPropagation();
        e.preventDefault();
      }}
    >
      <PohCard bodyClassName="p-0">
        <header className="d-flex justify-content-between">
          <h5 className="ps-2 mt-2">{name}</h5>
          <div>
            <PohButton icon={IconsEnum.close} onClick={handleToggle} />
          </div>
        </header>
        <PohTabs tabs={tabs} />
      </PohCard>
    </div>
  );
};

export default HikingRouteToolbar;
