import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { downloadGpx, IGetGPXStringTracks } from '@apps/Routes/@helpers/gpx.helper';
import { getBaseRouteDataAsync, getRouteObjectsAsync } from '@apps/Routes/@services/routes.service';
import { IBaseRouteObjectLine, RouteObjectType } from '@apps/Routes/@types/routes.types';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohLoader from '@ui-kit/Loader';

const HikingRouteDownloadButton = () => {
  const hikingData = React.useContext(HikingContext);

  const [isLoading, setIsLoading] = React.useState(false);

  if (!hikingData) return null;

  const downloadFullGpx = async (asRoute = true, join = false, onlyInDistance = false) => {
    try {
      setIsLoading(true);
      if (!hikingData.route.id) throw new Error('has no route');
      const { routeData: routeInfo } = await getBaseRouteDataAsync(hikingData.route.id);
      const routeObjects = await getRouteObjectsAsync(hikingData.route.id);
      const ro = routeObjects.toSorted((a, b) => a.order - b.order);
      let lines: IGetGPXStringTracks[] = ro
        .filter((r) => r.type === RouteObjectType.Line && (!onlyInDistance || r.is_in_distance))
        .map((r) => ({
          name: r.name,
          description: r.description,
          coordinates: (r as IBaseRouteObjectLine).points,
        }));
      if (join) {
        lines = [
          lines.reduce<IGetGPXStringTracks>(
            (acc, val) => {
              acc.description += val.name + ';\n';
              acc.coordinates.push(...val.coordinates);
              return acc;
            },
            { name: 'joined', description: '', coordinates: [] },
          ),
        ];
      }

      downloadGpx(
        lines,
        ro
          .filter((r) => r.type === RouteObjectType.Point)
          .map((r) => ({ name: r.name, description: r.description, coordinate: r.coordinates })),
        {
          asRoute,
          name: routeInfo?.name,
          description: routeInfo?.description,
          author: routeInfo?.author?.name,
          date: new Date(routeInfo?.dateCreate ?? new Date()),
        },
      );
    } catch (e) {
      notificationHelper.error((e as Error).message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <PohButton
      size={ButtonSize.Small}
      variant={ButtonVariant.Light}
      className="ms-2 me-2"
      onClick={(e) => downloadFullGpx(true, e.altKey, e.ctrlKey)}
      title={[
        'Скачать маршрут похода в формате GPX',
        'Alt + Click. Одной ниткой',
        'Ctrl + Click. Только учитываемые в дистанции',
      ].join('\n')}
      disabled={isLoading}
    >
      {isLoading ? <PohLoader /> : <PohIcon name={IconsEnum.download} />} gpx
    </PohButton>
  );
};

export default HikingRouteDownloadButton;
