import React from 'react';

import * as L from 'leaflet';
import { createRoot } from 'react-dom/client';

import 'leaflet/dist/leaflet.css';
import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { setMarkerObstacle, setMarkerStyles } from '@apps/Routes/@helpers/leaflet.helper';
import {
  setMarkerPass,
  setMarkerSimpleIcon,
  setPolylineStyles,
} from '@apps/Routes/@helpers/routeObjects.helper';
import { mapRouteObjectToPolylineStyle } from '@apps/Routes/@helpers/routeObjectStyles.helper';
import { getBaseRouteDataAsync, getRouteObjectsAsync } from '@apps/Routes/@services/routes.service';
import {
  IBaseRoute,
  IMapType,
  IRouteObject,
  RouteObjectType,
} from '@apps/Routes/@types/routes.types';
import { getMap } from '@helpers/leafletHelper';
import PohAlert from '@ui-kit/Alert';
import PohLoader from '@ui-kit/Loader';

import HikingRouteToolbar from './HikingRouteToolbar';
import style from './style.module.less';
import 'leaflet-fullscreen/dist/Leaflet.fullscreen.min';
import 'leaflet-fullscreen/dist/leaflet.fullscreen.css';

interface IHikingRoutePlannedProps {
  id_route: number;
}

const HikingRoutePlanned: React.FC<IHikingRoutePlannedProps> = ({ id_route }) => {
  const [mapData, setMapData] = React.useState<{
    routeData: IBaseRoute;
    typeData: IMapType;
  } | null>(null);
  const [routeObjectsData, setRouteObjectsData] = React.useState<IRouteObject[]>([]);

  const [err, setErr] = React.useState<Error>();

  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const layerGroupRef = React.useRef<L.FeatureGroup>(null);
  const factGroupRef = React.useRef<L.FeatureGroup>(null);

  React.useEffect(() => {
    if (mapRef.current || !ref.current || !mapData || !routeObjectsData) {
      return;
    }

    if (!mapRef.current) {
      mapRef.current = getMap(ref.current as HTMLElement, {
        fullscreenControl: true,
        fadeAnimation: true,
      });

      L.tileLayer(mapData.typeData.tileUrlTmpl).addTo(mapRef.current);
      layerGroupRef.current = L.featureGroup().addTo(mapRef.current);
      factGroupRef.current = L.featureGroup().addTo(mapRef.current);
    }

    layerGroupRef.current && layerGroupRef.current.clearLayers();

    if (mapData.routeData.bounds)
      mapRef.current.fitBounds(mapData.routeData.bounds, { paddingBottomRight: [0, 200] });

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    const legend = L.control({ position: 'topright' });

    legend.onAdd = function () {
      const div = L.DomUtil.create('div');
      const root = createRoot(div);

      mapRef.current &&
        root.render(
          <HikingRouteToolbar
            name={mapData.routeData.name}
            map={mapRef.current}
            routeObjects={routeObjectsData}
          />,
        );

      return div;
    };
    legend.addTo(mapRef.current);

    watermarkToMap(mapRef.current);

    routeObjectsData.forEach((a) => {
      if (a.type === RouteObjectType.Point) {
        const pl = L.marker(a.coordinates);

        setMarkerSimpleIcon(pl, a.color);
        setMarkerStyles(pl, { color: a.color, opacity: a.is_in_distance ? 1 : 0.5 });
        if (a.obstacle) {
          setMarkerObstacle(pl, a.obstacle);
        }
        a.obstacle &&
          setMarkerPass(
            pl,
            {
              name: a.obstacle.name,
              altitude: a.obstacle.altitude,
              category: a.obstacle.category,
            },
            a.is_in_distance,
          );

        if (a.name.length) {
          pl.bindTooltip(`${a.name}\n${a.obstacle?.comment ?? ''}`);
        }
        if (a.description.length) {
          pl.bindPopup(a.description);
        }

        layerGroupRef.current && pl.addTo(layerGroupRef.current);
      } else if (a.type === RouteObjectType.Line) {
        const pl = new L.Polyline(a.points);

        setPolylineStyles(pl, mapRouteObjectToPolylineStyle(a));

        layerGroupRef.current && pl.addTo(layerGroupRef.current);
      }
    });

    const bounds = layerGroupRef.current?.getBounds();
    if (bounds && bounds.isValid())
      mapRef.current.fitBounds(bounds, { paddingBottomRight: [5, 320] });
  }, [ref.current, mapData, routeObjectsData]);

  React.useEffect(() => {
    const getData = async () => {
      try {
        const [d1, d2] = await Promise.all([
          getBaseRouteDataAsync(id_route),
          getRouteObjectsAsync(id_route),
        ]);
        setMapData(d1);
        setRouteObjectsData(d2);
      } catch (e) {
        setErr(e as Error);
      }
    };

    getData();
  }, [id_route]);

  if (mapData == null || routeObjectsData == null) {
    return <PohLoader />;
  }

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  return (
    <div className={style.hikingRoute}>
      <div ref={ref} className={style.oneHikingMapContainer} />
    </div>
  );
};

export default HikingRoutePlanned;
