import { showModal } from '@ui-kit/Modal';

import HikingRadishModal from './index';

export function radishConfirmAsync(title = 'Отказ от участия в походе'): Promise<string | null> {
  return new Promise((resolve) => {
    showModal({
      title,
      flush: true,
      children: (closeHandler: () => void) => (
        <HikingRadishModal
          onSend={(comment) => {
            resolve(comment);
            closeHandler();
          }}
          onCancel={() => {
            resolve(null);
            closeHandler();
          }}
        />
      ),
    });
  });
}
