import React from 'react';

import { hikingMemberDatesShift } from '@apps/Hiking/@services/hiking.service';
import { IHiker, IHikingData } from '@apps/Hiking/@types/hiking.types';
import { getInputDate, getSQLDate } from '@helpers/dateHelper';
import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

interface IHikingMemberTimeEditModalProps {
  hiker: IHiker;
  hikingData: IHikingData | null;
  close: () => void;
}

const HikingMemberTimeEditModal: React.FC<IHikingMemberTimeEditModalProps> = ({
  hiker,
  close,
  hikingData,
}) => {
  const [modelData, setModelData] = React.useState({
    dateFrom: hiker.dateFrom ? getSQLDate(hiker.dateFrom) : null,
    dateTo: hiker.dateTo ? getSQLDate(hiker.dateTo) : null,
  });

  if (!hikingData) return <>No hiking data</>;

  const handleSave = () => {
    hikingMemberDatesShift({
      id_user: hiker.idUser,
      id_hiking: hikingData.id,
      d1:
        modelData.dateFrom && new Date(modelData.dateFrom) > hikingData.start
          ? getSQLDate(new Date(modelData.dateFrom))
          : '',
      d2:
        modelData.dateTo && new Date(modelData.dateTo) > hikingData.start
          ? getSQLDate(new Date(modelData.dateTo))
          : '',
    }).then((res) => {
      if (res.success) {
        close();
        success('Сохранено');
        window.location.reload();
      } else {
        err(res?.error || 'Ошибка');
      }
    });
  };

  const handleChange = (fieldName: string) => (value: string) =>
    setModelData({ ...modelData, [fieldName]: value });

  return (
    <PohContainer
      as="form"
      onSubmit={(e: React.FormEvent) => {
        e.preventDefault();
        handleSave();
      }}
    >
      <PohRow>
        <PohCol sm={12} className="mb-sm-3 d-flex flex-column" style={{ gap: 12 }}>
          <PohInput
            label="Дата начала"
            type={InputTypes.datetimeLocal}
            value={
              modelData.dateFrom && +modelData.dateFrom?.length > 10
                ? getInputDate(new Date(modelData.dateFrom))
                : ''
            }
            onChange={handleChange('dateFrom')}
            message="Оставить пустым если со старта"
            min={getInputDate(hikingData.start)}
            max={getInputDate(hikingData.finish)}
          />
          <PohInput
            label="Дата окончания"
            type={InputTypes.datetimeLocal}
            value={
              modelData.dateTo && +modelData.dateTo?.length > 10
                ? getInputDate(new Date(modelData.dateTo))
                : ''
            }
            onChange={handleChange('dateTo')}
            message="Оставить пустым если до финиша"
            min={getInputDate(hikingData.start)}
            max={getInputDate(hikingData.finish)}
          />
        </PohCol>
      </PohRow>
      <footer className="mt-4 mb-n2">
        <PohButton variant={ButtonVariant.Secondary} onClick={close}>
          Отмена
        </PohButton>{' '}
        &nbsp;
        <PohButton variant={ButtonVariant.Primary} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </PohContainer>
  );
};

export default HikingMemberTimeEditModal;
