import React from 'react';

import {
  getHikingRouteVariants,
  hikingRouteVariantAdd,
  hikingRouteVariantDelete,
  hikingRouteVariantVote,
  IHikingRouteVariantDTO,
} from '@apps/Hiking/@services/hikingRoutes.service';
import { selectOneRoute } from '@apps/Routes/RoutesList/selectRouteModal';
import PageLoader from '@components/PageLoader';
import { formatDistance } from '@helpers/formatHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

function HikingRouteVote({ id_hiking }: { id_hiking: number }) {
  const [variants, setVariants] = React.useState<IHikingRouteVariantDTO[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const d = await getHikingRouteVariants(id_hiking);
      setVariants(d);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_hiking]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err)
    return (
      <div>
        <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>
      </div>
    );

  return (
    <section>
      <h3>Выбор варианта маршрута</h3>
      <PohRow>
        {!variants.length ? (
          <PohCol sm={12}>
            <div className="text-info">
              Мы еще не определились с маршрутом. Нажмите палец вверх за самый привлекательный
              маршрут или добавьте свой вариант
            </div>
          </PohCol>
        ) : (
          variants.map((variant) => {
            const handleDeleteVote = async () => {
              try {
                if (!window.confirm('Точно удалить?')) return;
                await hikingRouteVariantDelete(id_hiking, +variant.route_id);
                notificationHelper.success('Удалено');
                load();
              } catch (error) {
                notificationHelper.error((error as Error).message);
              }
            };

            const handleAddVote = async () => {
              try {
                await hikingRouteVariantVote(id_hiking, +variant.route_id);
                notificationHelper.success('Ваш голос учтён');
                load();
              } catch (error) {
                notificationHelper.error((error as Error).message);
              }
            };

            return (
              <PohCol key={variant.route_id} sm={4}>
                <PohCard
                  img={variant.route_preview}
                  header={
                    <div className="d-flex justify-content-between">
                      {variant.route_name}
                      <strong>{formatDistance(+variant.distance)}</strong>
                    </div>
                  }
                  links={[
                    <a
                      key="view-route"
                      href={`/routes/${variant.route_id}`}
                      target="_blank"
                      rel="noreferrer"
                    >
                      Посмотреть маршрут
                    </a>,
                  ]}
                >
                  <p className="m-0 text-truncate" title={variant.route_desc}>
                    {variant.route_desc}
                  </p>
                  <div>
                    <small>
                      {variant.author_name} {variant.date_create}
                    </small>
                  </div>

                  <footer className="d-flex justify-content-end">
                    {variant.my === '1' && (
                      <PohButton icon={IconsEnum.trash} onClick={handleDeleteVote} />
                    )}
                    <span style={{ position: 'relative' }} className="ms-auto">
                      <PohButton
                        icon={IconsEnum['thumbs-up']}
                        onClick={handleAddVote}
                        variant={variant.my_vote === '1' ? ButtonVariant.Primary : undefined}
                      />
                      <PohBadge
                        style={{ position: 'absolute', left: '64%', bottom: '64%' }}
                        variant={+variant.vote_count > 0 ? BadgeVariant.Success : undefined}
                      >
                        {variant.vote_count}
                      </PohBadge>
                    </span>
                  </footer>
                </PohCard>
              </PohCol>
            );
          })
        )}
      </PohRow>
      <PohRow className="mt-3">
        <PohCol sm={12}>
          <PohButton
            onClick={async () => {
              try {
                const selectedRouteItem = await selectOneRoute();
                await hikingRouteVariantAdd(id_hiking, selectedRouteItem.id);
                notificationHelper.success('Вариант добавлен!');
                load();
              } catch (error) {
                notificationHelper.error((error as Error).message);
              }
            }}
            variant={ButtonVariant.Info}
            block
          >
            Предложить свой вариант маршрута
          </PohButton>
        </PohCol>
      </PohRow>
    </section>
  );
}

export default HikingRouteVote;
