import { confirmModal } from '@ui-kit/Modal';

import OnePositionModalContent from '../OnePositionModalContent';

export default function showModalAboutPositionAsync(id_position: number, actionName?: string) {
  return confirmModal({
    children: <OnePositionModalContent id_position={+id_position} />,
    showConfirm: !!actionName,
    confirmText: actionName,
    cancelText: 'Закрыть',
  });
}
